79: async function loadLocalEnvFile(envPath) {
80:   try {
81:     const raw = await readFile(envPath, 'utf8');
82:     raw.split(/\r?\n/).forEach((line) => {
83:       const trimmed = line.trim();
84:       if (!trimmed || trimmed.startsWith('#')) return;
85: 
86:       const eqIndex = line.indexOf('=');
87:       if (eqIndex === -1) return;
88: 
89:       const key = line.slice(0, eqIndex).trim();
90:       let value = line.slice(eqIndex + 1).trim();
91:       if (!key || Object.prototype.hasOwnProperty.call(process.env, key)) return;
92: 
93:       if (
94:         (value.startsWith('"') && value.endsWith('"')) ||
95:         (value.startsWith('\'') && value.endsWith('\''))
96:       ) {
97:         value = value.slice(1, -1);
98:       }
99: 
100:       value = value
101:         .replace(/\\n/g, '\n')
102:         .replace(/\\r/g, '\r');
103:       process.env[key] = value;
104:     });
105:   } catch (err) {
106:     if (err?.code !== 'ENOENT') throw err;
107:   }
108: }
